import{_ as i,C as t,o as r,c as a,ai as s,E as d}from"./chunks/framework.kPxgjqLK.js";const b=JSON.parse('{"title":"Der 30-Tage-Plan","description":"","frontmatter":{"title":"Der 30-Tage-Plan"},"headers":[],"relativePath":"kapitel/11-30-tage-plan.md","filePath":"kapitel/11-30-tage-plan.md"}'),h={name:"kapitel/11-30-tage-plan.md"};function l(u,e,o,g,c,f){const n=t("FeedbackForm");return r(),a("div",null,[e[0]||(e[0]=s('<h2 id="kapitel-11-der-30-tage-plan" tabindex="-1">Kapitel 11: Der 30-Tage-Plan <a class="header-anchor" href="#kapitel-11-der-30-tage-plan" aria-label="Permalink to &quot;Kapitel 11: Der 30-Tage-Plan&quot;">​</a></h2><h2 id="vom-experiment-zur-produktiven-routine" tabindex="-1">Vom Experiment zur produktiven Routine <a class="header-anchor" href="#vom-experiment-zur-produktiven-routine" aria-label="Permalink to &quot;Vom Experiment zur produktiven Routine&quot;">​</a></h2><p>Sie haben jetzt zehn Kapitel gelesen. Sie kennst die Werkzeuge, die Konzepte, die Muster und die Sicherheitsregeln. Jetzt kommt der Teil, der über alles andere entscheidet: der Anfang.</p><p>Wissen hilft nichts, wenn es nicht in Handlungen übergeht. Und bei Agenten ist der erste Schritt erfahrungsgemäß der schwierigste, nicht weil die Technik so schwer ist, sondern weil so viele Möglichkeiten auf einmal offen stehen, dass man nicht weiß, wo man anfangen soll.</p><p>Dieser 30-Tage-Plan nimmt Ihnen diese Entscheidung ab. Er ist bewusst konservativ aufgebaut, weil ein langsamer, gründlicher Start zu einem System führt, dem Sie vertrauen, während ein schneller, unkontrollierter Start zu einem System führt, das Sie irgendwann misstrauisch wieder abschaltest.</p><h2 id="die-grundlogik-des-plans" tabindex="-1">Die Grundlogik des Plans <a class="header-anchor" href="#die-grundlogik-des-plans" aria-label="Permalink to &quot;Die Grundlogik des Plans&quot;">​</a></h2><p>Der Plan folgt einer Grundlogik, die sich in der Praxis bewährt hat, sowohl aus der Anthropic-Forschung zu wirksamen Agenten als auch aus konkreten Rollout-Erfahrungen mit kleinen Unternehmen und Selbständigen in 2025 und 2026.</p><p>Die Grundlogik lautet: Ein Workflow, dann messen, dann erweitern. In den ersten sieben Tagen wird eine einzige Routine eingerichtet und täglich genutzt. In den zweiten sieben Tagen werden zwei weitere Routinen hinzugefügt. In den dritten sieben Tagen werden Sicherheit und Qualität gehärtet. In den vierten sieben Tagen wird die Wirkung gemessen und der nächste Quartal geplant.</p><p>Jede Woche hat ein klares Lieferobjekt: etwas, das am Ende der Woche funktioniert und täglich genutzt werden kann. Das ist kein akademischer Plan, sondern ein operativer.</p><h2 id="vorbereitung-die-woche-vor-dem-start" tabindex="-1">Vorbereitung: Die Woche vor dem Start <a class="header-anchor" href="#vorbereitung-die-woche-vor-dem-start" aria-label="Permalink to &quot;Vorbereitung: Die Woche vor dem Start&quot;">​</a></h2><p>Bevor der Plan beginnt, lohnen sich drei Vorbereitungsschritte, die zusammen nicht mehr als zwei Stunden dauern.</p><p>Der erste Schritt ist das Baseline-Audit. Schreibe auf, welche fünf Aufgaben in Ihrer Arbeit die meiste Zeit kosten und sich dabei regelmäßig wiederholen. Notiere für jede Aufgabe: Wie oft pro Woche tritt sie auf? Wie lange dauert sie im Durchschnitt? Was wäre das Ergebnis, wenn Sie sie halbieren könntest? Diese Grundlinie braucht Sie später zum Messen.</p><p>Der zweite Schritt ist die Werkzeugauswahl. Entscheide, mit welchem Werkzeug Sie beginnst. Wenn Sie projektbezogene Aufgaben am Schreibtisch delegieren willst, ist Claude Code der empfohlene Einstieg. Wenn Sie einen Agenten willst, der unterwegs erreichbar ist, ist Hermes mit Telegram-Anbindung der richtige Start. Wenn Sie technische Automatisierungen im Vordergrund hast, beginne mit Codex.</p><p>Der dritte Schritt ist die erste CLAUDE.md oder AGENTS.md. Schreibe eine erste Version dieser Konfigurationsdatei mit den grundlegenden Informationen über Sie und Ihre Arbeit: was Sie tun, wen Sie als Kunden hast, welche Projekte gerade laufen, welche Stilregeln für Texte gelten und was der Agent niemals ohne Rückfrage tun soll. Diese Datei muss nicht perfekt sein. Sie wird sich in den nächsten Wochen weiterentwickeln.</p><h2 id="woche-1-eine-routine-jeden-tag" tabindex="-1">Woche 1: Eine Routine, jeden Tag <a class="header-anchor" href="#woche-1-eine-routine-jeden-tag" aria-label="Permalink to &quot;Woche 1: Eine Routine, jeden Tag&quot;">​</a></h2><p>Das Ziel der ersten Woche ist einfach: Sie nutzen einen Agenten für eine einzige Aufgabe, jeden Tag, und Sie prüfen jedes Ergebnis sorgfältig.</p><p>Die empfohlene Startroutine für die meisten Selbständigen ist die Meeting-Nachbereitung aus Kapitel 7. Sie ist klar definiert, hat ein prüfbares Ergebnis und spart sofort spürbar Zeit. Wenn Sie in der ersten Woche keine Meetings nachbereiten musst, nimm die E-Mail-Triage oder das tägliche Morgenbriefing.</p><p>An Tag 1 richtest Sie die Routine ein: Werkzeug starten, Konfigurationsdatei laden, erste Aufgabe formulieren, Ergebnis prüfen. An Tag 2 nutzt Sie die Routine mit einer echten Aufgabe und notierst, was gut funktioniert hat und was nicht. An Tag 3 bis 5 nutzt Sie die Routine täglich und verbesserst den Skill oder die Konfiguration auf Basis Ihrer Erfahrungen. An Tag 6 prüfst Sie die Memory-Datei des Agenten: Sind die gespeicherten Informationen noch aktuell? Fehlt etwas? An Tag 7 schreibst Sie eine kurze Notiz: Was hat die Woche gebracht? Wie viel Zeit hat die Routine gespart? Was muss verbessert werden?</p><p>Das klingt nach wenig. Aber ein Agent, den Sie nach sieben Tagen wirklich verstehst, ist wertvoller als fünf Agenten, die Sie nach sieben Tagen halb eingerichtet hast.</p><p>Messziel Woche 1: Die eine Routine läuft täglich, die Ergebnisse werden konsequent geprüft, und Sie haben ein Gefühl dafür, wie der Agent in Ihrem Kontext arbeitet.</p><h2 id="woche-2-zwei-weitere-routinen" tabindex="-1">Woche 2: Zwei weitere Routinen <a class="header-anchor" href="#woche-2-zwei-weitere-routinen" aria-label="Permalink to &quot;Woche 2: Zwei weitere Routinen&quot;">​</a></h2><p>In der zweiten Woche erweiterst Sie das System um zwei weitere Routinen. Die Wahl hängt von Ihren Baseline-Audit-Ergebnissen ab. Nehmen wir als Beispiel an, Ihre drei zeitintensivsten Aufgaben waren Meeting-Nachbereitung, Recherche für Beiträge und die wöchentliche Backoffice-Runde.</p><p>In Woche 1 hast Sie Meeting-Nachbereitung eingerichtet. In Woche 2 fügst Sie einen Recherche-Skill und den Freitagsabschluss hinzu.</p><p>An Tag 8 richtest Sie den Recherche-Skill ein: Was soll jede Recherche enthalten? Fakten mit Quellen, Unsicherheiten markiert, Kurzfazit vorangestellt. An Tag 9 nutzt Sie den Skill mit einem echten Rechercheauftrag und prüfst das Ergebnis auf Qualität und Vollständigkeit. An Tag 10 und 11 feinerst Sie den Skill auf Basis der Erfahrungen. An Tag 12 richtest Sie den Freitagsabschluss-Skill ein: Was soll der Agent am Freitag tun? Belege der Woche prüfen, offene Aufgaben listen, nächste Woche vorbereiten. An Tag 13 führst Sie den Freitagsabschluss durch und prüfst das Ergebnis. An Tag 14 schreibst Sie Ihre zweite Wochennotiz: Was haben die drei Routinen zusammen gebracht? Welche Aufgaben kosten jetzt weniger Zeit?</p><p>Messziel Woche 2: Drei Routinen laufen regelmäßig, die Ergebnisse werden konsequent geprüft und Sie haben erste belastbare Zahlen über die tatsächliche Zeitersparnis.</p><h2 id="woche-3-sicherheit-und-qualitat-harten" tabindex="-1">Woche 3: Sicherheit und Qualität härten <a class="header-anchor" href="#woche-3-sicherheit-und-qualitat-harten" aria-label="Permalink to &quot;Woche 3: Sicherheit und Qualität härten&quot;">​</a></h2><p>In der dritten Woche wird nicht erweitert, sondern gesichert. Das ist die Woche, in der Sie das System robuster machst, damit es zuverlässig bleibt, wenn die erste Begeisterung nachlässt.</p><p>An Tag 15 prüfst Sie die Berechtigungen jeder laufenden Routine: Hat der Agent nur die Rechte, die er braucht? Sind externe Kommunikation und Dateiänderungen außerhalb der definierten Arbeitsbereiche blockiert?</p><p>An Tag 16 richtest Sie mindestens einen Hook ein: entweder einen Protokoll-Hook, der nach jeder Sitzung eine kurze Notiz schreibt, oder einen Sicherheits-Hook, der E-Mail-Sendeanfragen automatisch zur Bestätigung markiert.</p><p>An Tag 17 machst Sie eine Qualitätsstichprobe: Nimm fünf Ergebnisse aus den letzten zwei Wochen und prüfe sie kritisch. Enthielten sie Fehler? Waren Quellen belegt? War das Format wie erwartet? Wenn Sie Muster erkennst, wo der Agent regelmäßig schwächelt, passe die Konfiguration an.</p><p>An Tag 18 prüfst Sie die Memory-Dateien erneut: Was hat der Agent in den letzten zwei Wochen gespeichert? Ist alles noch aktuell? Gibt es Widersprüche?</p><p>An Tag 19 bereitest Sie ein Notfall-Protokoll vor: Was tust Sie, wenn eine Routine falsche Ergebnisse liefert? Wo können Sie den Agenten sofort stoppen? Wie machst Sie fehlerhafte Aktionen rückgängig?</p><p>An Tag 20 und 21 nutzt Sie das System normal, aber mit besonderer Aufmerksamkeit: Beobachte genau, was der Agent tut, und notiere alles, was unerwartet ist, egal ob positiv oder negativ.</p><p>Messziel Woche 3: Das System ist sicherer, überwachter und stabiler. Sie haben ein gutes Gefühl dafür, wo die Grenzen des Agenten liegen und wie Sie bei Problemen reagierst.</p><h2 id="woche-4-messen-auswerten-vorausschauen" tabindex="-1">Woche 4: Messen, Auswerten, Vorausschauen <a class="header-anchor" href="#woche-4-messen-auswerten-vorausschauen" aria-label="Permalink to &quot;Woche 4: Messen, Auswerten, Vorausschauen&quot;">​</a></h2><p>Die vierte Woche ist die Woche der Bilanz und der Planung.</p><p>An Tag 22 führst Sie ein erstes Wirkungsmessungg durch. Vergleiche die Baseline aus der Vorbereitungswoche mit dem aktuellen Stand. Wie viel Zeit spart jede Routine pro Woche? Was hat sich an der Qualität der Ergebnisse verändert? Gibt es Aufgaben, bei denen der Agent unerwartet gut oder unerwartet schwach ist?</p><p>Eine einfache Methode: Schreibe für jede der drei laufenden Routinen drei Zahlen auf. Die Zeit vor dem Agenten, die Zeit mit dem Agenten und die eingeschätzte Qualität des Ergebnisses auf einer Skala von eins bis fünf. Das dauert zehn Minuten und gibt Ihnen eine belastbare Grundlage für die nächsten Entscheidungen.</p><p>An Tag 23 und 24 überarbeitest Sie die Konfigurationsdateien auf Basis aller Erfahrungen der letzten vier Wochen. Aktualisiere die CLAUDE.md oder AGENTS.md mit allem, was Sie über Ihre eigene Arbeitsweise gelernt hast. Füge neue Stilregeln hinzu, die sich als wichtig herausgestellt haben. Entferne veraltete oder irrelevante Einträge.</p><p>An Tag 25 und 26 planst Sie den nächsten Monat. Welche drei bis fünf neuen Routinen würden Ihrer Arbeit am meisten nützen? Welche Aufgaben aus dem Backlog könnten mit den erworbenen Fähigkeiten angegangen werden? Welche Werkzeuge möchtest Sie tiefer kennenlernen?</p><p>An Tag 27 schreibst Sie eine kurze Zusammenfassung des ersten Monats. Nicht für andere, sondern für Sie. Was hat funktioniert? Was nicht? Was hast Sie über Ihren eigenen Arbeitsstil gelernt? Was wirst Sie im nächsten Monat anders machen?</p><p>An Tag 28 bis 30 nutzt Sie das System im normalen Rhythmus, mit dem Gefühl, dass es jetzt Ihr eigenes ist. Nicht mehr ein Experiment, sondern ein Werkzeug, das Sie kennst und dem Sie vertrauen, innerhalb der Grenzen, die Sie gesetzt haben.</p><p>Messziel Woche 4: Sie haben belastbare Zahlen über die Wirkung, einen Plan für den nächsten Monat und ein persönliches Agenten-System, das in Ihrer Arbeit wirklich verankert ist.</p><h2 id="kennzahlen-die-selbstandige-verfolgen-sollten" tabindex="-1">Kennzahlen, die Selbständige verfolgen sollten <a class="header-anchor" href="#kennzahlen-die-selbstandige-verfolgen-sollten" aria-label="Permalink to &quot;Kennzahlen, die Selbständige verfolgen sollten&quot;">​</a></h2><p>Eine kurze, praktische Liste der Kennzahlen, die über den Erfolg der eigenen Agentenpraxis Auskunft geben.</p><p>Die erste Kennzahl ist die eingesparte Zeit pro Woche nach Routinekategorie: Kommunikation, Recherche, Backoffice, Content. Sie müssen das nicht minutengenau tracken. Eine Schätzung auf 15-Minuten-Basis reicht.</p><p>Die zweite Kennzahl ist die Fehlerrate. Wie oft enthielt das Ergebnis eines Agenten einen Fehler, der vor der Verwendung korrigiert werden musste? Wenn diese Zahl steigt, ist das ein Hinweis darauf, dass Kontext veraltet ist, der Skill ungenau definiert wurde oder das Modell sich verändert hat.</p><p>Die dritte Kennzahl ist die Freigaberate. Wie viele Agentenergebnisse nutzt Sie direkt oder nach kleiner Anpassung, und bei wie vielen musst Sie von Grund auf neu schreiben? Eine hohe Freigaberate bedeutet, dass der Agent gut konfiguriert ist. Eine niedrige Freigaberate bedeutet, dass entweder die Aufgabe für Agentenunterstützung noch nicht reif ist oder die Konfiguration überarbeitet werden muss.</p><p>Die vierte Kennzahl sind die monatlichen Kosten. API-Kosten, Tool-Abonnements, Zeit für Konfiguration und Pflege. Wenn die Kosten die eingesparte Zeit in Wert übersteigen, ist die Konfiguration nicht effizient.</p><h2 id="haufige-stolpersteine-und-wie-sie-sie-vermeidest" tabindex="-1">Häufige Stolpersteine und wie Sie sie vermeidest <a class="header-anchor" href="#haufige-stolpersteine-und-wie-sie-sie-vermeidest" aria-label="Permalink to &quot;Häufige Stolpersteine und wie Sie sie vermeidest&quot;">​</a></h2><p>Aus der Praxis des Agentenrollouts in kleinen Unternehmen und bei Selbständigen kristallisieren sich vier häufige Stolpersteine heraus.</p><p>Der erste Stolperstein ist der Start mit zu vielen Werkzeugen gleichzeitig. Die Verlockung ist groß, alle vier Werkzeuge dieses Buches parallel einzurichten. Das Ergebnis ist fast immer, dass keines davon wirklich gut konfiguriert wird und die ersten Erfahrungen frustrierend sind. Starte mit einem Werkzeug, einem Monat, drei Routinen.</p><p>Der zweite Stolperstein ist die fehlende Konfigurationspflege. Eine CLAUDE.md, die nicht aktuell ist, führt zu einem Agenten, der mit veralteten Informationen arbeitet. Reserviere fünf Minuten pro Woche für eine kurze Aktualisierung. Das reicht.</p><p>Der dritte Stolperstein ist das Deaktivieren von Sicherheitsabfragen, weil sie lästig erscheinen. Nach wenigen Wochen, wenn das Vertrauen in den Agenten gestiegen ist, ist die Versuchung groß, die Bestätigungsanfragen abzuschalten. Tu es nicht. Sicherheitsabfragen sind keine Ineffizienz. Sie sind der Mechanismus, durch den Sie wissen, was der Agent tut.</p><p>Der vierte Stolperstein ist das Ausbleiben der Stichproben. Je länger eine Routine läuft, desto seltener werden die Ergebnisse genau geprüft. Plane jeden Monat eine strukturierte Qualitätsprüfung ein, auch wenn das System gut zu laufen scheint. Modelle werden aktualisiert. Kontexte verändern sich. Regelmäßige Prüfung ist die einzige Möglichkeit, Qualitätsverluste früh zu erkennen.</p><h2 id="der-plan-als-schleife-nicht-als-endpunkt" tabindex="-1">Der Plan als Schleife, nicht als Endpunkt <a class="header-anchor" href="#der-plan-als-schleife-nicht-als-endpunkt" aria-label="Permalink to &quot;Der Plan als Schleife, nicht als Endpunkt&quot;">​</a></h2><p>Dreißig Tage sind kein Endpunkt. Sie sind der erste Durchlauf einer Schleife, die sich vierteljährlich wiederholen sollte.</p><p>Jedes Quartal: Neue Baseline messen. Routinen überarbeiten oder erneuern. Einen oder zwei neue Anwendungsfälle hinzufügen. Sicherheitskonfigurationen prüfen. Werkzeuge auf aktuelle Versionen und neue Funktionen prüfen.</p><p>Diese vierteljährliche Schleife hält das System aktuell und relevant, ohne dass es zu einem Vollzeitprojekt wird. Ein Selbständiger, der drei Stunden pro Quartal in die Pflege seines Agenten-Systems investiert und dafür jede Woche drei bis vier Stunden einspart, macht ein sehr gutes Geschäft.</p><p>Das persönliche Agenten-System, das Sie in diesem Monat aufgebaut hast, wird in drei Monaten besser sein. In einem Jahr wird es ein Bestandteil Ihrer Arbeit sein, den Sie nicht mehr missen willst, weil Sie wissen, wie viel Zeit und mentale Energie es Ihnen zurückgibt.</p>',60)),d(n)])}const m=i(h,[["render",l]]);export{b as __pageData,m as default};
